INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(14822, 0, 0, 'Come to me and see what the future holds for you!', 12, 0, 100, 0, 0, 0, 'Sayge'),
(14822, 0, 1, 'Come speak with me, and what once was cloudy shall become crystal clear.', 12, 0, 100, 0, 0, 0, 'Sayge'),
(14822, 0, 2, 'Fear not!  All fortunes can be discerned for those who know the way.', 12, 0, 100, 0, 0, 0, 'Sayge'),
(14822, 0, 3, 'The longer you wait, the less future you have for me to foretell.', 12, 0, 100, 0, 0, 0, 'Sayge'),
(14823, 0, 0, 'Everyone enjoying themselves so far?  That\'s great!  Welcome to the Darkmoon Faire, the greatest show on all of Azeroth!  Make sure that you speak with Yebb and his friends here while you\'re taking in Neblegear\'s Darkmoon Zoo Bizarre.', 12, 0, 100, 0, 0, 0, 'Silas Darkmoon'),
(14823, 0, 1, 'Come one, come all.  Welcome to the Darkmoon Faire!  Don\'t be shy.  Step right up to Lhara and buy yourself an exotic artifact from far off lands.  If you\'re one of the lucky few who have found Darkmoon Cards, have a word with Professor Paleo.  Hungry?  Thirsty?  You\'re in luck!  Refreshments are available right here from Sylannia and Stamp.  I recommend the Darkmoon Special Reserve to wash down some Red Hot Wings.  And if the future is what you seek, then run, don\'t walk, to speak with Sayge.', 12, 0, 100, 0, 0, 0, 'Silas Darkmoon'),
(14823, 0, 2, 'Welcome one and all to the Darkmoon Faire, the greatest event in all the world!  We have it all... delicious food, strong drink, exotic artifacts, fortunes read, amazing prizes and excitement without end!  Don\'t forget to turn in your Darkmoon Faire Prize Tickets to Gelvas Grimegate!  All it takes is five or more and you\'re on your way to the most wondrous prizes on all of Azeroth.  Everybody is a winner!', 12, 0, 100, 0, 0, 0, 'Silas Darkmoon'),
(14823, 0, 3, 'Welcome one and all to the greatest show on all of Azeroth... the Darkmoon Faire!  Adventure and excitement await, don\'t be shy!  Mysteries and prizes for both the young and the old are here for the taking.  And be sure to speak with the professor about any Darkmoon Cards that you have come across during your travels!', 12, 0, 100, 0, 0, 0, 'Silas Darkmoon'),
(14823, 0, 4, 'Greetings friends, and welcome to the greatest show on Azeroth!$B$BPlease, step right up and take in all we have to offer.  Ride the rides and see the sights!  Amaze at the wonders that the Darkmoon Faire has uncovered in this vast and mysterious world!  We have spared no expense in bringing you excitement that children of all ages will delight in!', 12, 0, 100, 0, 0, 0, 'Silas Darkmoon'),
(14823, 0, 5, 'Come one, come all!  Welcome to the Darkmoon Faire!  Do you crave adventure?  Do you seek exotic and mysterious treasures?  Then look no further!  You, my friend, have come to the right place!  Dive right in and take part in all that the Faire has to offer!  We\'ll be at this location all week, so be sure to tell your friends and loved ones!', 12, 0, 100, 0, 0, 0, 'Silas Darkmoon'),
(14823, 0, 6, 'We\'re back and better than ever!  It\'s the Darkmoon Faire friend, and it\'s your lucky day!  Sparing no expense, we\'ve gathered wonders and treats from around the world for your delight.  Whether you\'re young or old, rich or poor, the Darkmoon Faire has it all!  Be sure to turn in your Darkmoon Faire Prize Tickets to Gelvas Grimegate, and choose from several exotic and wondrous prizes!', 12, 0, 100, 0, 0, 0, 'Silas Darkmoon'),
(14823, 1, 0, 'Come one, come all.  Welcome to the Darkmoon Faire!  Don\'t be shy.  Step right up to Lhara and buy yourself an exotic artifact from far off lands.  If you\'re one of the lucky few who have found Darkmoon Cards, have a word with Professor Paleo.  Hungry?  Thirsty?  You\'re in luck!  Refreshments are available right here from Sylannia and Stamp.  I recommend the Darkmoon Special Reserve to wash down some Red Hot Wings.  And if the future is what you seek, then run, don\'t walk, to speak with Sayge.', 12, 0, 100, 0, 0, 0, 'Silas Darkmoon'),
(14823, 1, 1, 'Come one, come all!  Welcome to the Darkmoon Faire!  Do you crave adventure?  Do you seek exotic and mysterious treasures?  Then look no further!  You, my friend, have come to the right place!  Dive right in and take part in all that the Faire has to offer!  We\'ll be at this location all week, so be sure to tell your friends and loved ones!', 12, 0, 100, 0, 0, 0, 'Silas Darkmoon'),
(14823, 1, 2, 'We\'re back and better than ever!  It\'s the Darkmoon Faire friend, and it\'s your lucky day!  Sparing no expense, we\'ve gathered wonders and treats from around the world for your delight.  Whether you\'re young or old, rich or poor, the Darkmoon Faire has it all!  Be sure to turn in your Darkmoon Faire Prize Tickets to Gelvas Grimegate, and choose from several exotic and wondrous prizes!', 12, 0, 100, 0, 0, 0, 'Silas Darkmoon'),
(14823, 1, 3, 'Welcome one and all to the greatest show on all of Azeroth... the Darkmoon Faire!  Adventure and excitement await, don\'t be shy!  Mysteries and prizes for both the young and the old are here for the taking.  And be sure to speak with the professor about any Darkmoon Cards that you have come across during your travels!', 12, 0, 100, 0, 0, 0, 'Silas Darkmoon'),
(14823, 1, 4, 'Greetings friends, and welcome to the greatest show on Azeroth!$B$BPlease, step right up and take in all we have to offer.  Ride the rides and see the sights!  Amaze at the wonders that the Darkmoon Faire has uncovered in this vast and mysterious world!  We have spared no expense in bringing you excitement that children of all ages will delight in!', 12, 0, 100, 0, 0, 0, 'Silas Darkmoon'),
(14823, 1, 5, 'Everyone enjoying themselves so far?  That\'s great!  Welcome to the Darkmoon Faire, the greatest show in all of Outland!  Make sure that you speak with Yebb and his friends here while you\'re taking in Neblegear\'s Darkmoon Zoo Bizarre.', 12, 0, 100, 0, 0, 0, 'Silas Darkmoon'),
(14823, 1, 6, 'Welcome one and all to the Darkmoon Faire, the greatest event in all the worlds!  We have it all... delicious food, strong drink, exotic artifacts, fortunes read, amazing prizes and excitement without end!  Don\'t forget to turn in your Darkmoon Faire Prize Tickets to Gelvas Grimegate!  All it takes is five or more and you\'re on your way to the most wondrous prizes in all of Outland.  Everybody is a winner!', 12, 0, 100, 0, 0, 0, 'Silas Darkmoon'),
(14828, 0, 0, 'Five tickets or five hundred, it doesn\'t matter friend, everybody is a winner!', 12, 0, 100, 0, 0, 0, 'Gelvas Grimegate'),
(14828, 0, 1, 'Mysterious prizes await the adventurous.  Step right up, step right up!', 12, 0, 100, 0, 0, 0, 'Gelvas Grimegate'),
(14828, 0, 2, 'Prizes!  Get your prizes right here!  Get over here and turn in your Darkmoon Prize Tickets for valuable prizes!', 12, 0, 100, 0, 0, 0, 'Gelvas Grimegate'),
(14828, 0, 3, 'Tickets! Redeem your Darkmoon Prize Tickets here!  Wondrous and exotic prizes are waiting for you!', 12, 0, 100, 0, 0, 0, 'Gelvas Grimegate'),
(14841, 0, 0, 'Step right up and take your best shot!', 12, 0, 100, 70, 0, 0, 'Rinling'),
(14841, 0, 1, 'Shoot for loot! Who wants to shoot for some loot?', 12, 0, 100, 70, 0, 0, 'Rinling'),
(14841, 1, 0, 'Guns, guns, guns! C\'mon, pal!', 12, 0, 100, 70, 0, 0, 'Rinling'),
(14841, 1, 1, 'Folks, I\'m handing out epics over here! Don\'t miss out!', 12, 0, 100, 70, 0, 0, 'Rinling'),
(14841, 1, 2, 'If you can shoot, you can score some sweet prizes!', 12, 0, 100, 70, 0, 0, 'Rinling'),
(14841, 1, 3, 'Come play a game so simple that even a $c can do it!', 12, 0, 100, 70, 0, 0, 'Rinling'),
(14841, 1, 4, 'Test your aim! Test your aim!', 12, 0, 100, 70, 0, 0, 'Rinling'),
(14841, 1, 5, 'Test your skill, win a prize!', 12, 0, 100, 70, 0, 0, 'Rinling'),
(14846, 0, 0, 'Come and take a look at my wares while you still can.  We\'re here all week, and then we\'re off to some far off land.', 12, 0, 100, 0, 0, 0, 'Lhara'),
(14846, 1, 0, 'Darkmoon Faire Cards?  See the Professor here for those.', 12, 0, 100, 0, 0, 0, 'Lhara'),
(14846, 1, 1, 'Every item that I have for sale I acquired myself.  You have my personal guarantee of authenticity.', 12, 0, 100, 0, 0, 0, 'Lhara'),
(14846, 1, 2, 'Have you any idea what I go through to bring these incomparable valuables to sell?  Come see them all for yourself!', 12, 0, 100, 0, 0, 0, 'Lhara'),
(14847, 0, 0, 'Darkmoon decks! Turn them in here!', 12, 0, 100, 0, 0, 0, 'Professor Thaddeus Paleo'),
(14847, 0, 1, 'Come speak with me if you have any Darkmoon Faire Cards.', 12, 0, 100, 0, 0, 0, 'Professor Thaddeus Paleo'),
(14847, 0, 2, 'Have you any Darkmoon Faire cards?  Come speak with me to learn more about them if you dare!', 12, 0, 100, 0, 0, 0, 'Professor Thaddeus Paleo'),
(14860, 0, 0, 'Hey, someone help me catch this thing!', 12, 0, 100, 0, 0, 0, 'Flik'),
(14860, 0, 1, 'It\'s getting away!', 12, 0, 100, 0, 0, 0, 'Flik'),
(14860, 0, 2, 'Get back here!', 12, 0, 100, 0, 0, 0, 'Flik'),
(14860, 0, 3, 'Frogs and leather balls for sale!', 12, 0, 100, 0, 0, 0, 'Flik'),
(14871, 0, 0, 'Jubjub?  Where are you, Jubjub?  Oh no!  Where did you go this time!', 12, 0, 100, 0, 0, 0, ''),
(14871, 1, 0, 'Hi Jubjub.  I missed you!', 12, 0, 100, 0, 0, 0, ''),
(15303, 0, 0, 'Don\'t worry about your weight, this cannon can handle any payload!', 12, 0, 100, 70, 0, 0, 'Maxima Blastenheimer'),
(15303, 1, 0, 'Cannon blast!  Who wants to get shot out of a cannon?', 12, 0, 100, 70, 0, 0, 'Maxima Blastenheimer'),
(15303, 1, 1, 'Step up to get blown up!', 12, 0, 100, 70, 0, 0, 'Maxima Blastenheimer'),
(15303, 1, 2, 'Transportation to the other end of the faire!', 12, 0, 100, 70, 0, 0, 'Maxima Blastenheimer'),
(23837, 0, 0, 'Scrying upon many insignificant situations within Icecrown, you stumble upon something interesting...', 42, 0, 100, 0, 0, 0, 'Eye of Lich King Ambient'),
(23837, 1, 0, 'There is a noise from behind you!', 41, 0, 100, 0, 0, 0, 'ELM General Purpose Bunny'),
(54485, 0, 0, 'Hey, hey $c! Think you can land a ring on a slow moving turtle?', 12, 0, 100, 70, 0, 0, 'Jessica Rogers'),
(54485, 0, 1, 'Simple game, for simple folk. Think you can manage it?', 12, 0, 100, 70, 0, 0, 'Jessica Rogers'),
(54485, 0, 2, 'Toss a ring, win a prize!', 12, 0, 100, 70, 0, 0, 'Jessica Rogers'),
(54485, 0, 3, 'You look like you\'ve got quite the arm there. Care to give this game a try?', 12, 0, 100, 70, 0, 0, 'Jessica Rogers'),
(54595, 0, 0, 'Silly, that\'s no dragon bone. It\'s probably from an elekk or something.', 12, 0, 100, 1, 0, 0, ''),
(54596, 0, 0, 'I\'ve found a bone, look!', 12, 0, 100, 396, 0, 0, 'Raan'),
(54596, 1, 0, 'D\'you think it\'s from a dragon? Or maybe a giant!', 12, 0, 100, 1, 0, 0, 'Raan'),
(54596, 2, 0, 'How d\'you know?', 12, 0, 100, 396, 0, 0, 'Raan'),
(54601, 0, 0, 'Hammer time!', 12, 0, 100, 70, 0, 0, 'Mola to Player'),
(54601, 0, 1, 'Whack some gnolls! Step right up and whack some gnolls!', 12, 0, 100, 70, 0, 0, 'Mola to Player'),
(54601, 0, 2, 'Hammer swingin\' fun! Who wants to swing a hammer?', 12, 0, 100, 70, 0, 0, 'Mola to Player'),
(54601, 0, 3, 'Swing a hammer, win a prize!', 12, 0, 100, 70, 0, 0, 'Mola to Player'),
(54601, 1, 0, 'Please stay out of the gaming area.', 42, 0, 100, 0, 0, 0, 'Mola to Player'),
(54605, 0, 0, 'Hey, hey! Command a tonk in glorious battle!', 12, 0, 100, 70, 0, 0, 'Finlay Coolshot'),
(54605, 0, 1, 'Step right up and try a tonk!', 12, 0, 100, 70, 0, 0, 'Finlay Coolshot'),
(54605, 0, 2, 'Tonks! We got tonks here!', 12, 0, 100, 70, 0, 0, 'Finlay Coolshot'),
(54605, 0, 3, 'We\'re under attack! Step up and do your part, $c!', 12, 0, 100, 70, 0, 0, 'Finlay Coolshot'),
(55264, 0, 0, 'Game tokens for sale! Come get your game tokens!', 12, 0, 100, 70, 0, 0, 'Sazz Coincatcher'),
